<template>
  <div class="song-card">
    <h2 class="song-name">{{ songData.songName }}</h2>

    <div class="song-cover">
      <img :src="songData.cover" :alt="songData.songName" class="cover-img" />
    </div>

    <div class="difficulty-wrapper">
      <div
        class="diff-item"
        v-for="diff in ['EZ', 'HD', 'IN', 'AT']"
        :key="diff"
      >
        <template v-if="songData[diff]?.old && songData[diff].old !== 0">
          <div class="diff-tag" :style="{ backgroundColor: songData[diff]?.color }">
            {{ diff }}
          </div>
          <div class="diff-numbers">
            <span class="old-val dt-num">{{ songData[diff].old.toFixed(1) }}</span>
            <span class="arrow">↓</span>
            <span class="new-val dt-num">{{ songData[diff].new.toFixed(1) }}</span>
            <span class="diff-val dt-num" :class="getDiffClass(songData[diff])">
              {{ getDiffText(songData[diff]) }}
            </span>
          </div>
        </template>
      </div>
    </div>
  </div>
</template>

<script setup>
import { useRouter } from 'vue-router'
const router = useRouter()

const props = defineProps({
  songData: { type: Object, required: true },
  songKey: { type: String, required: true },
  mainColor: { type: String, required: true },
  textColor: { type: String, required: true }
})

const getDiffText = (diff) => {
  const oldVal = Number(diff.old)
  const newVal = Number(diff.new)
  const dif = newVal - oldVal
  return dif > 0 ? `+${dif.toFixed(1)}` : dif.toFixed(1)
}

// 涨跌方向决定颜色：涨绿、跌红、不变灰
const getDiffClass = (diff) => {
  const dif = Number(diff.new) - Number(diff.old)
  if (dif > 0) return 'is-up'
  if (dif < 0) return 'is-down'
  return 'is-flat'
}
</script>

