/**
 * 定数变更取数（/files/lvmdf/lvmdf<版本>.json）。
 */
import { loadJson } from './jsonCache.js'
import { decorateSongMap } from './common.js'

export async function getLvmdfMap(jsonPath) {
  try {
    const jsonData = await loadJson(jsonPath)
    return decorateSongMap(jsonData, ['EZ', 'HD', 'IN', 'AT'])
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('请求路径：', jsonPath)
    return {}
  }
}
