<script setup>
import { useOpenSong } from '../../api/openSong.js'
const openSong = useOpenSong()
import { getLvmdfMap } from '../../api/lvmdf.js'
import lvmdfCard from '../../components/cards/lvmdfCard.vue'
import { ref, onMounted, computed, onUnmounted } from 'vue'
import { useRemScale } from '../../utils/rem.js'

import { useRouter } from 'vue-router'

useRemScale()

const router = useRouter()
const songlvmdf = ref({})
const selectedVersion = ref('3.18.4')

const commonConfig = {
  color: '#212426',
  text: '#ffffff'
}

const versionConfig = {
  '1.5.0': { file: '/files/lvmdf/lvmdf1.5.0.json' },
  '2.0.0': { file: '/files/lvmdf/lvmdf2.0.0.json' },
  '2.5.0': { file: '/files/lvmdf/lvmdf2.5.0.json' },
  '3.2.0': { file: '/files/lvmdf/lvmdf3.2.0.json' },
  '3.5.0': { file: '/files/lvmdf/lvmdf3.5.0.json' },
  '3.9.0': { file: '/files/lvmdf/lvmdf3.9.0.json' },
  '3.11.0': { file: '/files/lvmdf/lvmdf3.11.0.json' },
  '3.15.1': { file: '/files/lvmdf/lvmdf3.15.1.json' },
  '3.18.3': { file: '/files/lvmdf/lvmdf3.18.3.json' },
  '3.18.4': { file: '/files/lvmdf/lvmdf3.18.4.json' },
  '3.20.0': { file: '/files/lvmdf/lvmdf3.20.0.json' },
}

const mainColor = computed(() => commonConfig.color)
const textColor = computed(() => commonConfig.text)

const fetchSongData = async () => {
  const filePath = versionConfig[selectedVersion.value].file
  const data = await getLvmdfMap(filePath)
  songlvmdf.value = data
}

const changeVersion = (version) => {
  selectedVersion.value = version
  fetchSongData()
}

onMounted(async () => {
  await fetchSongData()
})


const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="dt-page">

    <div class="dt-tabs version-tabs">
      <button
        v-for="version in ['1.5.0', '2.0.0', '2.5.0', '3.2.0', '3.5.0', '3.9.0', '3.11.0', '3.15.1', '3.18.3', '3.18.4', '3.20.0']"
        :key="version"
        class="dt-tab"
        :class="{ 'dt-tab--active': selectedVersion === version }"
        @click="changeVersion(version)"
      >
        {{ version }}
      </button>
    </div>

    <div class="card-grid">
      <lvmdf-card
        v-for="(songItem, songKey) in songlvmdf"
        :key="songKey"
        :song-data="songItem"
        :song-key="songKey" @click="openSong(songKey)"
        :main-color="mainColor"
        :text-color="textColor"
      />
    </div>

    <div v-if="!Object.keys(songlvmdf).length" class="dt-empty">
      该版本没有定数变更记录
    </div>
  </div>
</template>

